import socket
import ssl
from tls_client import make_client_context


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert against cafile and hostname,
    and return the server's greeting bytes up to and including the first newline or up to 4096 bytes."""
    if server_hostname is None:
        server_hostname = host
    ctx = make_client_context(cafile)
    with socket.create_connection((host, port)) as sock:
        with ctx.wrap_socket(sock, server_hostname=server_hostname) as tls_sock:
            # Read up to 4096 bytes or until a newline is found
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    break
            # Return bytes up to and including the first newline, or all if none
            nl_index = data.find(b"\n")
            if nl_index >= 0:
                return bytes(data[: nl_index + 1])
            return bytes(data)

import socket
import ssl
from tls_client import make_client_context


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server certificate and hostname,
    and return the server's greeting bytes up to and including the first newline,
    or until the connection closes, at most 4096 bytes.

    Raises ssl.SSLError or ssl.CertificateError on verification failure.
    """
    if server_hostname is None:
        server_hostname = host

    context = make_client_context(cafile=cafile)
    with socket.create_connection((host, port)) as sock:
        with context.wrap_socket(sock, server_hostname=server_hostname) as tls_sock:
            # Read up to 4096 bytes or until first newline
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    # Stop reading after the first newline
                    break
            # Return bytes up to and including the first newline if any
            if b"\n" in data:
                index = data.index(b"\n") + 1
                return bytes(data[:index])
            else:
                return bytes(data)

import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify the server certificate against cafile and server_hostname,
    and return the server's greeting bytes up to and including the first newline or until close (max 4096 bytes).

    Raises ssl.SSLError or ssl.CertificateError on verification failure."""
    if server_hostname is None:
        server_hostname = host
    # Create a TCP socket and connect
    sock = socket.create_connection((host, port))
    try:
        # Wrap the socket with TLS, verifying cert and hostname
        tls_sock = wrap_client_socket(sock, server_hostname, cafile)
        try:
            # Read up to 4096 bytes or until newline
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    # Connection closed
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    # Stop after first newline
                    break
            # Return up to and including the first newline if present
            newline_index = data.find(b"\n")
            if newline_index != -1:
                return bytes(data[:newline_index + 1])
            else:
                return bytes(data)
        finally:
            tls_sock.close()
    finally:
        sock.close()

import socket
