def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port verifying server certificate and hostname,
    then return the bytes received up to and including the first newline or until
    connection closes (max 4096 bytes). Raises ssl.SSLError or ssl.CertificateError
    on verification failure."""
    if server_hostname is None:
        server_hostname = host
    with socket.create_connection((host, port)) as sock:
        with wrap_client_socket(sock, server_hostname, cafile) as tls_sock:
            buffer = bytearray()
            while len(buffer) < 4096:
                data = tls_sock.recv(4096 - len(buffer))
                if not data:
                    # Connection closed
                    break
                buffer.extend(data)
                if b"\n" in buffer:
                    # Stop reading after first newline
                    break
            # Return up to and including the first newline if present
            if b"\n" in buffer:
                idx = buffer.index(b"\n") + 1
                return bytes(buffer[:idx])
            else:
                return bytes(buffer)
